import json, pathlib, pandas as pd, numpy as np
from datetime import datetime
from zoneinfo import ZoneInfo

base = pathlib.Path('/app/dataset')
cal = json.loads((base/'sensors_calibration.json').read_text())['enterprise_platform']['deployment_environments']['system_config']['farms']
farms = pd.read_csv(base/'farms.csv')
reg = pd.read_csv(base/'farm_registry.csv')
farms['key'] = farms['farm_name'].str.strip().str.lower()
reg['key'] = reg['farm_name'].str.strip().str.lower()
meta = reg.merge(farms[['key','timezone','installed_capacity_kw']], on='key', how='left').set_index('farm_id')
start_utc = pd.Timestamp('2024-03-15 00:00:00', tz='UTC')
end_utc = pd.Timestamp('2024-03-16 00:00:00', tz='UTC')
completed_maintenance = {
    'FARM_C': [(pd.Timestamp('2024-03-16 08:00:00'), pd.Timestamp('2024-03-16 12:00:00'))],
    'FARM_F': [(pd.Timestamp('2024-03-15 12:00:00'), pd.Timestamp('2024-03-15 14:00:00'))],
}
unit_factor_energy = {'kwh':1.0,'mwh':1000.0,'wh':0.001,'btu':0.00029307107}

def read_raw(farm_id):
    path = base / f'production_{farm_id}.csv'
    raw = path.read_bytes()
    enc = 'utf-16' if raw.startswith((b'\xff\xfe', b'\xfe\xff')) else 'utf-8'
    text = raw.decode(enc)
    sep = ';' if ';' in text.splitlines()[3] else ','
    df = pd.read_csv(path, skiprows=3, sep=sep, encoding=enc, dtype=str)
    return df, sep

def parse_ts(s):
    if pd.isna(s):
        return pd.NaT
    s = str(s).strip()
    if not s:
        return pd.NaT
    for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S'):
        try:
            return pd.Timestamp(datetime.strptime(s, fmt))
        except Exception:
            pass
    return pd.NaT

def normalize_number_str(s):
    if s is None:
        return None
    s = str(s).strip()
    if not s or s in {'ERR', 'N/A', 'offline', 'timeout', 'null'}:
        return None
    if '.' in s and ',' in s:
        return s.replace('.', '').replace(',', '.')
    if ',' in s:
        return s.replace(',', '.')
    return s

def parse_num(series):
    return pd.to_numeric(series.map(normalize_number_str), errors='coerce')

def prep(farm_id):
    df, sep = read_raw(farm_id)
    value_col = cal[farm_id]['calibration_data']['value_column_name']
    cols = [df.columns[0], 'inverter_temperature_C', value_col]
    datasets = {
        'full': df.drop_duplicates().copy(),
        'sub': df[cols].drop_duplicates().copy(),
    }
    out = {}
    for k, d in datasets.items():
        ts_col = d.columns[0]
        d['parsed_ts'] = d[ts_col].map(parse_ts)
        d['value_num'] = parse_num(d[value_col])
        d['temp_num'] = parse_num(d['inverter_temperature_C'])
        d = d[d['parsed_ts'].notna()].copy()
        tz = ZoneInfo(meta.loc[farm_id, 'timezone'])
        d['ts_local'] = pd.DatetimeIndex(d['parsed_ts']).tz_localize(tz)
        d['ts_utc'] = d['ts_local'].dt.tz_convert('UTC')
        out[k] = d
    return out

for method_dup in ['full','sub']:
    print('\nDUP', method_dup)
    for power_mode in ['nominal','forward_next','backward_prev']:
        print(' mode', power_mode)
        out = {}
        for farm_id in meta.index:
            datasets = prep(farm_id)
            d = datasets[method_dup].copy()
            for st_local, en_local in completed_maintenance.get(farm_id, []):
                tz = ZoneInfo(meta.loc[farm_id, 'timezone'])
                st_utc = st_local.tz_localize(tz).tz_convert('UTC')
                en_utc = en_local.tz_localize(tz).tz_convert('UTC')
                d = d[~((d['ts_utc'] >= st_utc) & (d['ts_utc'] < en_utc))]
            spikes = d[d['temp_num'] > 85]['ts_utc']
            if len(spikes):
                mask = pd.Series(False, index=d.index)
                for spike in spikes:
                    mask |= (d['ts_utc'] > spike) & (d['ts_utc'] < spike + pd.Timedelta(minutes=45))
                d = d[~mask]
            d = d[(d['ts_utc'] >= start_utc) & (d['ts_utc'] < end_utc)].copy()
            d['corrected'] = d['value_num'] - cal[farm_id]['calibration_data']['calibration_offset']
            d = d[d['corrected'].notna() & (d['corrected'] >= 0)].copy()
            d = d.sort_values('ts_utc').reset_index(drop=True)
            info = cal[farm_id]['sensor_info']
            if info['reading_type'] == 'energy':
                total = d['corrected'].sum() * unit_factor_energy[info['unit'].strip().lower()]
            else:
                if d.empty:
                    total = 0.0
                else:
                    if power_mode == 'nominal':
                        all_d = datasets[method_dup].copy()
                        diffs = all_d['ts_utc'].sort_values().diff().dropna().dt.total_seconds()/60
                        diffs = diffs[diffs > 0]
                        cadence = diffs.mode().iloc[0] if not diffs.empty else 0
                        total = d['corrected'].sum() * cadence / 60.0
                    elif power_mode == 'forward_next':
                        ts = d['ts_utc']
                        next_ts = ts.shift(-1).fillna(end_utc)
                        dur = (next_ts - ts).dt.total_seconds()/3600
                        dur = dur.clip(lower=0)
                        total = (d['corrected'] * dur).sum()
                    else:
                        ts = d['ts_utc']
                        prev_ts = ts.shift(1).fillna(start_utc)
                        dur = (ts - prev_ts).dt.total_seconds()/3600
                        dur = dur.clip(lower=0)
                        total = (d['corrected'] * dur).sum()
            out[farm_id] = round(total)
        print(out)
